#!/bin/sh
cat >/dev/null
case "$PGP_MODE" in
 err) echo "gpg: no valid OpenPGP data found." >&2;;
 mid) i=0; while [ $i -lt 260 ]; do printf 'é:packet %d\n' $i; i=$((i+1)); done;;
 long) i=0; while [ $i -lt 400 ]; do printf 'é:packet %d\n' $i; i=$((i+1)); done;;
 *) echo "# off=0 ctb=85 tag=1 hlen=3 plen=268"; echo ":pubkey enc packet: version 3, algo 1, keyid 0123456789ABCDEF";;
esac

